import json

def rank2(cols):
    piv={}
    for x in cols:
        while x:
            p=x.bit_length()-1
            if p in piv:x^=piv[p]
            else:piv[p]=x;break
    return len(piv)
def betti(Fs):
    vertices=sorted(set().union(*map(set,Fs)))
    dim=max(map(len,Fs))-1
    faces=[sorted(set(c for F in Fs for c in combinations(F,j+1))) for j in range(dim+1)]
    ranks=[0]
    for j in range(1,dim+1):
        idx={F:i for i,F in enumerate(faces[j-1])}
        ranks.append(rank2([sum(1<<idx[G] for G in combinations(F,j)) for F in faces[j]]))
    ranks.append(0)
    return [len(faces[j])-ranks[j]-ranks[j+1]-(j==0) for j in range(dim+1)]
